import{_ as t,l as r,o,c as i,v as a,p as n,x as d,d as s,i as l,S as E}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"窗口函数","description":"","frontmatter":{"title":"窗口函数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/window-functions.md","filePath":"cs/window-functions.md","lastUpdated":1789023840000}'),p={name:"cs/window-functions.md"};function R(A,e,h,_,m,B){const c=r("Mermaid");return o(),i("div",null,[e[1]||(e[1]=a('<h1 id="窗口函数" tabindex="-1">窗口函数 <a class="header-anchor" href="#窗口函数" aria-label="Permalink to &quot;窗口函数&quot;">​</a></h1><div class="epigraph"><p>窗口在结果行上再看一组邻居：分区、排序、帧；聚合不收缩行数，排名与前后行参照同一张输出。</p><footer>—— 据 SQL:2003 窗口；Ramakrishnan and Gehrke 对 OLAP 扩展；ISO SQL 对 OVER 子句的整理</footer></div><p><a href="/cs/sql-aggregation">上一课</a>把多行收成一组一行。本课不重定义 <code>SUM</code>。缺口是：用户要「每行保留，同时看该行所在分区的合计、名次、上一行」——收缩会丢掉要展示的行。窗口函数用 <code>OVER</code> 给每一输入行指定一个窗口，计算标量后仍吐出原行（外加结果列）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分组把订单收成「每顾客一行」。若还要列出每张订单、并标「该顾客订单总额」「该单在顾客内的名次」，<code>GROUP BY</code> 做不到，除非自连接聚合结果。窗口把这种「按邻居算、行不删」收进声明。缺口不是新的存储引擎，而是查询语言：<code>PARTITION BY</code> 划区（像分组键但不收缩），<code>ORDER BY</code> 给区内序，帧（<code>ROWS</code>/<code>RANGE</code>）再从序上切一段。</p><p>排名（<code>ROW_NUMBER</code>/<code>RANK</code>/<code>DENSE_RANK</code>）依赖区内序，与聚合窗口不同：后者可在无序分区上对全体行求 <code>SUM</code>。<code>LAG</code>/<code>LEAD</code> 是帧上的前后参照。本课不把每一帧排除子句写完，只钉：窗口算子的输入输出基数相同（过滤仍可由外层 <code>WHERE</code> 做，但那是另一层）。</p><p><span class="marginnote">逻辑处理顺序大致是：<code>FROM</code>/<code>WHERE</code>/<code>GROUP BY</code>/<code>HAVING</code> 之后才算窗口，再 <code>SELECT</code> 与 <code>ORDER BY</code>。故窗口看不到将被 <code>HAVING</code> 丢掉的组，也不能在同一层 <code>WHERE</code> 里引用窗口结果——要包一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把窗口写成 \\(\\omega\\)：对当前行 \\(t\\)，窗口是同分区里按序、按帧选出的多重集 \\(W(t)\\)，再在 \\(W(t)\\) 上求聚合或排名。物理上可排序 + 分区扫描，或把帧做成增量（滑动合计）。本课不规定算子融合；只要求指称按行定义，而不是「先 GROUP 再神秘展开」。</p><p>帧默认在有 <code>ORDER BY</code> 时常是「从分区头到当前行」（累计），无序分区上则常是整个分区。写错帧会把「累计」变成「全区重复同一合计」。这是语义，不是优化器 bug。</p>',10)),(o(),n(E,null,{default:d(()=>[l(c,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%88%86%E7%BB%84%E4%B9%8B%E5%90%8E%E7%9A%84%E8%A1%8C%22%5D%20--%3E%20PART%5B%22PARTITION%20BY%22%5D%0A%20%20PART%20--%3E%20ORD%5B%22%E5%8C%BA%E5%86%85%20ORDER%20BY%22%5D%0A%20%20ORD%20--%3E%20FR%5B%22%E5%B8%A7%20ROWS%20%2F%20RANGE%22%5D%0A%20%20FR%20--%3E%20VAL%5B%22%E6%AF%8F%E8%A1%8C%E4%B8%80%E4%B8%AA%E6%A0%87%E9%87%8F%22%5D%0A%20%20VAL%20--%3E%20OUT%5B%22%E8%A1%8C%E6%95%B0%E4%B8%8D%E5%8F%98%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口与分组可同句出现：先 \\(\\gamma\\) 再 \\(\\omega\\)，或只 \\(\\omega\\)。优化器把窗口当防火墙：不能把窗口谓词推到分区之前，除非谓词不依赖窗口结果。多个窗口可能共享同一分区排序，计划可以一次排序服务多个 <code>OVER</code>——那是实现，指称仍是分别求值。</p><p><code>RANGE</code> 按值相等切帧，<code>ROWS</code> 按物理邻居条数切；重复排序键时两者不同。NULL 在窗口 <code>ORDER BY</code> 里的位置由 <code>NULLS FIRST/LAST</code> 约定，与 <a href="/cs/sql-null">三值</a> 比较规则一致，本课不另造序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲流式窗口（事件时间、水位线）；那是后课分析与流。也不把窗口当成索引结构。子查询里套窗口、再与外层相关，下一课去相关要处理的是嵌套，不是本课的帧。</p><p>后课默认：需要「行上带邻居统计」时用窗口，需要「一行代表一组」时用 <code>GROUP BY</code>。两者都是声明算子，不是应用循环。</p><p>累计、排名、前后行是同一套 <code>OVER</code> 参数的不同函数，不是三种查询语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口不收缩行数；分区像分组键，帧决定邻居集合。</li><li>逻辑上窗口在 <code>HAVING</code> 之后；引用窗口结果要再包一层。</li><li>去相关下一课：嵌套查询如何回到连接与窗口可执行的形状。</li><li>出处：SQL:2003；Ramakrishnan and Gehrke；ISO SQL。</li></ul>',9))])}const S=t(p,[["render",R]]);export{O as __pageData,S as default};
